import {WORKSTATION_REWARDS} from './engine.js';
export const TERMINAL_CASES=[
{title:'The abandoned workstation',tag:'COMMAND-LINE BASICS',sector:0,reward:WORKSTATION_REWARDS[0],brief:'You found a resistance workstation in an abandoned depot. Read its recovery order, inspect the PC, and reconnect to its gateway.',hint:'Try dir, cd tickets, type job.txt, ipconfig, then ping 192.168.1.1. Finish with submit.',commands:['dir','cd tickets','type job.txt','ipconfig','ping 192.168.1.1'],lesson:'dir lists files, cd changes folders, and type reads a text file. These are Windows-style commands in this simulated PC.'},
{title:'A severed lifeline',tag:'LINK DIAGNOSIS',sector:1,reward:WORKSTATION_REWARDS[1],brief:'A resistance safehouse has gone silent. Find the local fault and restore its connection to the relay.',hint:'Inspect ipconfig. If the media is disconnected, use repair cable, then ping 192.168.1.1 and submit.',commands:['ipconfig','repair cable','ping 192.168.1.1'],lesson:'A disconnected cable is a physical-layer fault. A good IP address cannot fix a missing link.'},
{title:'Ghost address',tag:'DHCP RECOVERY',sector:2,reward:WORKSTATION_REWARDS[2],brief:'A recovered terminal has no valid DHCP lease. Restore its address and reach the supply-cache server at 192.168.1.20.',hint:'Read ipconfig. An address beginning 169.254 is link-local. Try ipconfig /renew, then ping 192.168.1.20 and submit.',commands:['ipconfig','ipconfig /renew','ping 192.168.1.20'],lesson:'A 169.254.x.x address can indicate IPv4 link-local fallback after DHCP fails. It is not a usable address for this 192.168.1.0/24 lab.'},
{title:'A route out of the dark',tag:'ROUTING INCIDENT',sector:3,reward:WORKSTATION_REWARDS[3],brief:'Local machines respond, but the remote resistance relay at 198.51.100.20 is unreachable. Recovered inventory identifies the router as 192.168.1.1.',hint:'Use route print or tracert 198.51.100.20. Set configure gateway 192.168.1.1, then ping 198.51.100.20 and submit.',commands:['route print','tracert 198.51.100.20','configure gateway 192.168.1.1','ping 198.51.100.20'],lesson:'A default gateway carries traffic to other networks. Hosts on this same local subnet can communicate without using it.'},
{title:'The missing directory',tag:'DNS INCIDENT',sector:4,reward:WORKSTATION_REWARDS[4],brief:'The reclaimed server at 192.168.1.20 responds, but portal.test does not. Restore access to the resistance directory; its DNS server is 192.168.1.53.',hint:'Compare ping 192.168.1.20 with nslookup portal.test. Use configure dns 192.168.1.53, repeat nslookup, then submit.',commands:['ping 192.168.1.20','nslookup portal.test','configure dns 192.168.1.53'],lesson:'DNS translates names into addresses. A working IP path does not prove that name resolution works.'},
{title:'The last human message',tag:'APPLICATION INCIDENT',sector:5,reward:WORKSTATION_REWARDS[5],brief:'The resistance message archive answers ping, but the page is unavailable. Restore the HTTP service and recover the last human transmission.',hint:'Try ping portal.test and curl http://portal.test. Use repair service, repeat curl, then submit.',commands:['ping portal.test','curl http://portal.test','repair service'],lesson:'Ping tests ICMP reachability. It does not prove HTTP works. A server returning HTTP 503 needs application-service investigation.'}
];
const GW='192.168.1.1',DNS='192.168.1.53',HOST='192.168.1.20',REMOTE='198.51.100.20';
export function newTerminal(id=0){return {id,cwd:'C:\\',link:id!==1,ip:id===2?'169.254.12.8':'192.168.1.10',gateway:id===3?'192.168.1.254':GW,dns:id===4?'192.168.1.99':DNS,service:id!==5,seen:[],fixed:false,verified:false};}
export function terminalCommand(t,input){
const raw=input.trim(),cmd=raw.toLowerCase().replace(/\s+/g,' ');const mark=k=>{if(!t.seen.includes(k))t.seen.push(k);};
if(!cmd)return {output:''};if(raw.length>160)return {output:'Keep commands under 160 characters.'};
const online=()=>t.link&&t.ip.startsWith('192.168.1.');
const result=output=>({output});
if(cmd==='help')return result('WINDOWS-STYLE LAB COMMANDS\n  dir | cd tickets | cd .. | type job.txt\n  ipconfig | ipconfig /renew\n  ping <address or portal.test>\n  tracert <address> | route print\n  nslookup portal.test | curl http://portal.test\n\nGAME-ONLY ACTIONS (not real OS commands)\n  repair cable | repair service\n  configure gateway <IPv4> | configure dns <IPv4>\n  submit — verify your work order\n  clear — clear the display\nNo command accesses your computer or a real network.');
if(cmd==='clear'||cmd==='cls')return {output:'Console cleared. Your current lab configuration is unchanged.',clear:true};
if(cmd==='dir')return result(t.cwd==='C:\\'?'Directory of C:\\\n<DIR> tickets':'Directory of C:\\tickets\njob.txt');
if(cmd==='cd tickets'||cmd==='cd c:\\tickets'){t.cwd='C:\\tickets';return result('C:\\tickets');}
if(cmd==='cd ..'||cmd==='cd \\'){t.cwd='C:\\';return result('C:\\');}
if(cmd==='cd')return result(t.cwd);
if(cmd==='type job.txt'){if(t.cwd!=='C:\\tickets')return result('File not found here. Use dir and cd tickets.');mark('read');return result('RECOVERY ORDER '+(t.id+1)+'\n'+TERMINAL_CASES[t.id].brief+'\n'+TERMINAL_CASES[t.id].hint);}
if(cmd==='ipconfig'){mark('inspect');return result('Windows-style IP Configuration [SIMULATED]\nEthernet adapter Lab:\n  Media state: '+(t.link?'Connected':'Media disconnected')+'\n  IPv4 Address: '+t.ip+'\n  Subnet Mask: '+(t.ip.startsWith('169.254.')?'255.255.0.0':'255.255.255.0')+'\n  Default Gateway: '+t.gateway+'\n  DNS Server: '+t.dns);}
if(cmd==='ipconfig /renew'){if(!t.link)return result('Cannot renew: media disconnected.');t.ip='192.168.1.10';if(t.id===2)t.fixed=true;return result('DHCP lease renewed.\nIPv4 Address: 192.168.1.10\nSubnet Mask: 255.255.255.0');}
if(cmd==='route print'){mark('route');return result('IPv4 Route Table [SIMULATED]\nNetwork Destination    Netmask            Gateway\n0.0.0.0                0.0.0.0            '+t.gateway+'\n192.168.1.0            255.255.255.0      On-link');}
if(cmd.startsWith('tracert ')){mark('route');const target=cmd.slice(8);if(![HOST,REMOTE,GW].includes(target))return result('This lab supports tracert to '+HOST+', '+REMOTE+', or '+GW+'.');if(!online())return result('1  Request timed out. Check the local link and IP configuration.');if(target===REMOTE&&t.gateway!==GW)return result('1  '+t.gateway+'  Request timed out.\nNo reachable default gateway.');return result('Tracing route to '+target+'\n1  '+(target===REMOTE?GW:target)+'  1 ms'+(target===REMOTE?'\n2  '+REMOTE+'  12 ms':'')+'\nTrace complete.');}
if(cmd.startsWith('ping ')){let target=cmd.slice(5);if(target==='portal.test'){if(!online()||t.dns!==DNS)return result('Ping request could not find host portal.test. Check name resolution.');target=HOST;}if(![HOST,GW,DNS,REMOTE].includes(target))return result('This simulated lab contains '+GW+', '+HOST+', '+DNS+', '+REMOTE+' and portal.test.');if(!online())return result('Destination host unreachable. Inspect the local link and IP configuration.');if(target===REMOTE&&t.gateway!==GW)return result('Request timed out. Local traffic works; check the default route.');mark('ping:'+target);if((t.id===1&&target===GW||t.id===2&&target===HOST||t.id===3&&target===REMOTE)&&t.fixed)t.verified=true;return result('Pinging '+target+' with 32 bytes of data:\nReply from '+target+': bytes=32 time=1ms TTL=64\nPackets: Sent = 4, Received = 4, Lost = 0 (0% loss)');}
if(cmd==='nslookup portal.test'){mark('dns');if(!online())return result('DNS request failed: local network unavailable.');if(t.dns!==DNS)return result('Server: '+t.dns+'\nDNS request timed out.\nThe configured DNS server is not responding.');if(t.id===4&&t.fixed)t.verified=true;return result('Server: lab-dns\nAddress: '+DNS+'\nName: portal.test\nAddress: '+HOST);}
if(cmd==='curl http://portal.test'){mark('http');if(!online())return result('curl: could not connect to host.');if(t.dns!==DNS)return result('curl: could not resolve host portal.test.');if(!t.service)return result('HTTP/1.1 503 Service Unavailable\nThe web service is stopped. The network path is working.');if(t.id===5&&t.fixed)t.verified=true;return result('HTTP/1.1 200 OK\nRESISTANCE ARCHIVE ONLINE.\nIf you can read this, we are still here.');}
if(cmd==='repair cable'){t.link=true;if(t.id===1)t.fixed=true;return result('[Simulation action] Cable reconnected. Verify the connection with ping.');}
if(cmd==='repair service'){if(!online())return result('Restore the network connection first.');t.service=true;if(t.id===5)t.fixed=true;return result('[Simulation action] Web service restarted. Verify with curl http://portal.test.');}
const config=/^configure (gateway|dns) (\d{1,3}(?:\.\d{1,3}){3})$/.exec(cmd);
if(config){if(config[2].split('.').some(n=>Number(n)>255))return result('Invalid IPv4 address. Each octet must be 0–255.');t[config[1]]=config[2];t.verified=false;if(t.id===3)t.fixed=t.gateway===GW;if(t.id===4)t.fixed=t.dns===DNS;return result('[Simulation action] '+config[1]+' set to '+config[2]+'. Test again before submitting.');}
if(cmd==='submit'){const evidence=[()=>t.seen.includes('read')&&t.seen.includes('inspect')&&t.seen.includes('ping:'+GW),()=>t.seen.includes('inspect')&&t.link&&t.verified,()=>t.seen.includes('inspect')&&online()&&t.verified,()=>t.seen.includes('route')&&t.gateway===GW&&t.verified,()=>t.seen.includes('dns')&&t.dns===DNS&&t.verified,()=>t.seen.includes('http')&&t.service&&t.verified][t.id]();return {output:evidence?'RECOVERY ORDER VERIFIED\n'+TERMINAL_CASES[t.id].lesson:'Work order not verified yet. Inspect the fault, make the repair, and test the result. Type help or open the case hint.',completed:evidence};}
return result('Command not recognized in this lab. Type help for supported commands.');
}
